import{_ as n,a0 as o,w as r,s as h,ao as p,I as l,x as t,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"用 Starship 定制你的 shell 提示符 | LCTT x X-CMD","titleTemplate":false,"description":"用 Starship 定制你的 shell 提示符 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Starship 定制你的 shell 提示符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Starship 定制你的 shell 提示符 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220207 Customize your shell prompt with Starship","title":"用 Starship 定制你的 shell 提示符","tag":"202202","desc":""},"relativePath":"202202/20220207 Customize your shell prompt with Starship.md","filePath":"[post].md"}'),d={name:"202202/20220207 Customize your shell prompt with Starship.md"};function u(g,s,b,k,c,m){const a=o("Link");return r(),h("div",null,[s[18]||(s[18]=p(`<h1 id="用-starship-定制你的-shell-提示符" tabindex="-1">用 Starship 定制你的 shell 提示符 <a class="header-anchor" href="#用-starship-定制你的-shell-提示符" aria-label="Permalink to “用 Starship 定制你的 shell 提示符”">​</a></h1><blockquote><p>控制你的提示符，让你需要的所有信息触手可及。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202202/14/232227pkh7bxi1a9asbfd5.jpg" alt=""></p><p>没有什么比我忘记在我的 Git 仓库中 <code>git add</code> 文件更让我恼火的了。我在本地测试，提交，然后推送，却发现在持续集成阶段失败了。更糟糕的是，我在 <code>main</code> 分支而不是特性分支上，并不小心推送到它。最好的情况是，因为分支保护而失败，我需要做一些操作才能把改动推送到一个分支。更糟糕的是，我没有正确配置分支保护，不小心直接推送到了 <code>main</code> 分支。</p><p>如果这些信息能在提示中直接获得，那不是很好吗？</p><p>在提示符中甚至还有更多有用的信息。虽然 Python 虚拟环境的名称在提示符中，但虚拟环境的 Python 版本却不在提示符中。</p><p>可以仔细地将 <code>PS1</code> 环境变量配置为所有相关的信息。这可能会变得很长，很烦人，而且调试起来并不简单。</p><p>这就是 Starship 被设计来解决的问题。</p><h3 id="安装-starship" tabindex="-1">安装 Starship <a class="header-anchor" href="#安装-starship" aria-label="Permalink to “安装 Starship”">​</a></h3><p>Starship 的初始设置只需要两个步骤：安装并配置你的 shell。安装可以很简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL https://starship.rs/install.sh</span></span></code></pre></div><p>阅读安装脚本，确保你理解它的作用，然后让它可执行并运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x install.sh</span></span>
<span class="line"><span>$ ./install.sh</span></span></code></pre></div><p>还有其他的安装方法，在其网站上有介绍。你可以在构建镜像的步骤中设置虚拟机或容器。</p><h3 id="配置-starship" tabindex="-1">配置 Starship <a class="header-anchor" href="#配置-starship" aria-label="Permalink to “配置 Starship”">​</a></h3><p>下一步是配置你的 shell 来使用它。要一次性尝试，假设 shell 是 <code>bash</code> 或 <code>zsh</code>，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ eval &quot;$(starship init $(basename $SHELL))&quot;</span></span></code></pre></div><p>你的提示符立即改变：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>localhost in myproject on  master</span></span>
<span class="line"><span>&gt;</span></span></code></pre></div><p>如果你喜欢你所看到的，把 <code>eval &quot;$(starship init $(basename $SHELL))&quot;</code> 添加到你的 shell 的 <code>rc</code> 文件中，使其永久化。</p><h3 id="自定义-starship" tabindex="-1">自定义 Starship <a class="header-anchor" href="#自定义-starship" aria-label="Permalink to “自定义 Starship”">​</a></h3>`,21)),l("p",null,[s[1]||(s[1]=t("默认安装假定你可以安装“电脑迷字体”，例如 ",-1)),i(a,{href:"https://github.com/belluzj/fantasque-sans"},{default:e(()=>[...s[0]||(s[0]=[t("Fantasque Sans Mono",-1)])]),_:1}),s[2]||(s[2]=t("。 特别是，你需要一种带有来自 Unicode 的“私有实现”部分的字形的字体。",-1))]),s[19]||(s[19]=p(`<p>这在控制终端时非常有效，但有时，终端的配置并不容易。例如，当使用一些浏览器内的 shell 抽象时，配置浏览器的字体可能是不太容易的。</p><p>该码位的最大用户是 Git 集成，它使用一个特殊的自定义符号来表示“分支”。禁用它可以通过使用文件 <code>~/.config/starship.toml</code> 来配置 <code>starship.rs</code>。</p><p>禁用分支符号是通过配置 <code>git_branch</code> 部分的 <code>format</code> 变量完成的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[git_branch]</span></span>
<span class="line"><span>format = &quot;on [$branch]($style) &quot;</span></span></code></pre></div><p><code>starship.rs</code> 的一个好处是，改变配置会立即生效。保存文件，按下<strong>回车</strong>，看看字体是否符合预期。</p><p>还可以配置提示符中不同部分的颜色。例如，如果 Python 部分的亮黄色在白色背景上有点难看，你可以配置为蓝色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[python]</span></span>
<span class="line"><span>style = &quot;blue bold&quot;</span></span></code></pre></div><p>许多语言都有配置支持，包括 Go、.NET 和 JavaScript。还支持显示命令的持续时间（只针对耗时超过阈值的命令）等。</p><h3 id="控制提示符" tabindex="-1">控制提示符 <a class="header-anchor" href="#控制提示符" aria-label="Permalink to “控制提示符”">​</a></h3><p>控制你的提示符，让你需要的所有信息触手可及。安装 Starship，让它为你工作，并享受吧！</p><hr>`,11)),l("p",null,[s[4]||(s[4]=t("via: ",-1)),i(a,{href:"https://opensource.com/article/22/2/customize-prompt-starship"},{default:e(()=>[...s[3]||(s[3]=[t("https://opensource.com/article/22/2/customize-prompt-starship",-1)])]),_:1})]),l("p",null,[s[9]||(s[9]=t("作者：",-1)),i(a,{href:"https://opensource.com/users/moshez"},{default:e(()=>[...s[5]||(s[5]=[t("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=t(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[t("lujun9972",-1)])]),_:1}),s[11]||(s[11]=t(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[7]||(s[7]=[t("geekpi",-1)])]),_:1}),s[12]||(s[12]=t(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[t("wxy",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[t("LCTT",-1)])]),_:1}),s[16]||(s[16]=t(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[t("Linux中国",-1)])]),_:1}),s[17]||(s[17]=t(" 荣誉推出",-1))])])}const y=n(d,[["render",u]]);export{S as __pageData,y as default};
